pub const fn get_latest_map(key: RegistryKey) -> Option<&'static phf::Map<&'static str, Tag>> {
    match key {
        RegistryKey::BannerPattern => Some(&BANNER_PATTERN_TAGS),
        RegistryKey::Block => Some(&BLOCK_TAGS),
        RegistryKey::DamageType => Some(&DAMAGE_TYPE_TAGS),
        RegistryKey::Dialog => Some(&DIALOG_TAGS),
        RegistryKey::Enchantment => Some(&ENCHANTMENT_TAGS),
        RegistryKey::EntityType => Some(&ENTITY_TYPE_TAGS),
        RegistryKey::Fluid => Some(&FLUID_TAGS),
        RegistryKey::GameEvent => Some(&GAME_EVENT_TAGS),
        RegistryKey::Instrument => Some(&INSTRUMENT_TAGS),
        RegistryKey::Item => Some(&ITEM_TAGS),
        RegistryKey::PaintingVariant => Some(&PAINTING_VARIANT_TAGS),
        RegistryKey::PointOfInterestType => Some(&POINT_OF_INTEREST_TYPE_TAGS),
        RegistryKey::Potion => Some(&POTION_TAGS),
        RegistryKey::Timeline => Some(&TIMELINE_TAGS),
        RegistryKey::WorldgenBiome => Some(&WORLDGEN_BIOME_TAGS),
        _ => None,
    }
}
